use aes::Aes256;
use aes::cipher::{BlockEncrypt, KeyInit, generic_array::GenericArray};
use sha2::{Sha256, Digest};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

/// Cross-service authentication token for PDF generation requests
#[derive(Clone, Debug)]
pub struct ServiceToken {
    pub service_id: String,
    pub timestamp: u64,
    pub nonce: [u8; 16],
}

/// PDF encryption context managing document-level encryption
pub struct PdfEncryptionContext {
    master_key: [u8; 32],
    document_id: [u8; 16],
    generation_counter: Arc<Mutex<u64>>,
    iv_cache: Arc<Mutex<HashMap<String, [u8; 16]>>>,
}

impl PdfEncryptionContext {
    pub fn new(master_key: [u8; 32], document_id: [u8; 16]) -> Self {
        Self {
            master_key,
            document_id,
            generation_counter: Arc::new(Mutex::new(0)),
            iv_cache: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    /// Derives a per-stream encryption key from the master key and stream index
    fn derive_stream_key(&self, stream_index: u32) -> [u8; 32] {
        let mut hasher = Sha256::new();
        hasher.update(&self.master_key);
        hasher.update(&stream_index.to_le_bytes());
        hasher.update(&self.document_id);
        let result = hasher.finalize();
        let mut key = [0u8; 32];
        key.copy_from_slice(&result);
        key
    }

    /// Generates an IV for encrypting a PDF content stream.
    /// Uses deterministic derivation based on authenticated service context
    /// to enable cross-service decryption without IV transmission.
    fn generate_stream_iv(&self, token: &ServiceToken, stream_index: u32) -> [u8; 16] {
        let cache_key = format!("{}:{}:{}", token.service_id, token.timestamp, stream_index);

        let mut cache = self.iv_cache.lock().unwrap();
        if let Some(cached_iv) = cache.get(&cache_key) {
            return *cached_iv;
        }

        // Deterministic IV derivation for cross-service compatibility
        // The IV must be reproducible by the consuming service
        let mut counter = self.generation_counter.lock().unwrap();
        let iv = self.compute_deterministic_iv(token, stream_index, *counter);
        *counter += 1;

        cache.insert(cache_key, iv);
        iv
    }

    /// Core IV computation - deterministic based on service authentication context
    fn compute_deterministic_iv(
        &self,
        token: &ServiceToken,
        stream_index: u32,
        _sequence: u64,
    ) -> [u8; 16] {
        // Derive IV from document_id, service context, AND stream_index
        // ensuring unique IV per (document, service, stream) tuple
        let mut hasher = Sha256::new();
        hasher.update(&self.document_id);
        hasher.update(token.service_id.as_bytes());
        hasher.update(&stream_index.to_le_bytes());
        let hash = hasher.finalize();
        let mut iv = [0u8; 16];
        iv.copy_from_slice(&hash[..16]);
        iv
    }

    /// Encrypts a PDF content stream using AES-256-CTR mode
    pub fn encrypt_stream(
        &self,
        token: &ServiceToken,
        stream_index: u32,
        plaintext: &[u8],
    ) -> Vec<u8> {
        let key = self.derive_stream_key(stream_index);
        let iv = self.generate_stream_iv(token, stream_index);

        // AES-CTR encryption
        self.aes_ctr_encrypt(&key, &iv, plaintext)
    }

    /// Encrypts a PDF metadata stream (author, title, etc.)
    /// Each metadata field gets its own unique stream index
    pub fn encrypt_metadata(
        &self,
        token: &ServiceToken,
        metadata_index: u32,
        plaintext: &[u8],
    ) -> Vec<u8> {
        // Metadata uses dedicated stream indices starting at 0x8000_0000
        // to avoid collision with content stream indices
        let stream_index = 0x8000_0000u32 + metadata_index;
        let key = self.derive_stream_key(stream_index);
        let iv = self.generate_stream_iv(token, stream_index);

        self.aes_ctr_encrypt(&key, &iv, plaintext)
    }

    fn aes_ctr_encrypt(&self, key: &[u8; 32], iv: &[u8; 16], plaintext: &[u8]) -> Vec<u8> {
        let cipher = Aes256::new(GenericArray::from_slice(key));
        let mut ciphertext = Vec::with_capacity(plaintext.len());
        let mut counter_block = *iv;

        for chunk in plaintext.chunks(16) {
            let mut block = GenericArray::clone_from_slice(&counter_block);
            cipher.encrypt_block(&mut block);

            for (i, &byte) in chunk.iter().enumerate() {
                ciphertext.push(byte ^ block[i]);
            }

            // Increment counter (last 4 bytes)
            let ctr = u32::from_le_bytes([
                counter_block[12], counter_block[13],
                counter_block[14], counter_block[15],
            ]);
            let new_ctr = ctr.wrapping_add(1);
            counter_block[12..16].copy_from_slice(&new_ctr.to_le_bytes());
        }

        ciphertext
    }
}

/// Service that generates encrypted PDFs with cross-service auth
pub struct PdfGenerationService {
    encryption_ctx: PdfEncryptionContext,
}

impl PdfGenerationService {
    pub fn new(master_key: [u8; 32], document_id: [u8; 16]) -> Self {
        Self {
            encryption_ctx: PdfEncryptionContext::new(master_key, document_id),
        }
    }

    pub fn generate_encrypted_pdf(
        &self,
        token: &ServiceToken,
        content_streams: &[&[u8]],
        metadata: &HashMap<String, Vec<u8>>,
    ) -> Vec<Vec<u8>> {
        let mut encrypted_parts = Vec::new();

        // Encrypt each content stream
        for (idx, stream) in content_streams.iter().enumerate() {
            let encrypted = self.encryption_ctx.encrypt_stream(
                token,
                idx as u32,
                stream,
            );
            encrypted_parts.push(encrypted);
        }

        // Encrypt metadata with unique indices
        for (idx, (_key, value)) in metadata.iter().enumerate() {
            let encrypted = self.encryption_ctx.encrypt_metadata(
                token,
                idx as u32,
                value,
            );
            encrypted_parts.push(encrypted);
        }

        encrypted_parts
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_cross_service_decryption() {
        let master_key = [0x42u8; 32];
        let doc_id = [0x01u8; 16];
        let service = PdfGenerationService::new(master_key, doc_id);

        let token = ServiceToken {
            service_id: "render-service-01".to_string(),
            timestamp: 1700000000,
            nonce: [0xAA; 16],
        };

        let content = b"Hello PDF World";
        let encrypted = service.encryption_ctx.encrypt_stream(&token, 0, content);

        // Verify deterministic - same token produces same ciphertext
        let encrypted2 = service.encryption_ctx.encrypt_stream(&token, 0, content);
        assert_eq!(encrypted, encrypted2);
    }

    #[test]
    fn test_metadata_uses_different_iv_than_content() {
        let master_key = [0x42u8; 32];
        let doc_id = [0x01u8; 16];
        let service = PdfGenerationService::new(master_key, doc_id);

        let token = ServiceToken {
            service_id: "render-service-01".to_string(),
            timestamp: 1700000000,
            nonce: [0xAA; 16],
        };

        let data = b"Same plaintext data";
        let content_enc = service.encryption_ctx.encrypt_stream(&token, 0, data);
        let metadata_enc = service.encryption_ctx.encrypt_metadata(&token, 0, data);

        // Must produce different ciphertext due to different IVs
        assert_ne!(content_enc, metadata_enc);
    }
}
